{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Private practice therapy and focused packages to help you navigate transitions and strong feelings. Confidential, practical, and collaborative care.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-root">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" viewBox="0 0 100 100" aria-hidden="true">
        <rect x="8" y="8" width="84" height="84" rx="16" fill="#ffffff" opacity="0.06" />
        <circle cx="50" cy="42" r="20" stroke="#2b5f5f" stroke-width="3" fill="none" />
        <path d="M30 70 C44 56, 56 56, 70 70" stroke="#2b5f5f" stroke-width="3" fill="none" stroke-linecap="round" />
      </svg>
      <div>
        <div class="business-name">{{BUSINESS_NAME}}</div>
        <div class="tagline">{{TAGLINE}}</div>
      </div>
    </div>
    <nav class="main-nav" aria-label="Primary navigation">
      <a href="/">Home</a>
      <a href="/about.html">About & Approach</a>
      <a href="/specialties.html">Specialties</a>
      <a href="/fees.html">Offerings & Fees</a>
      <a href="/faq.html">FAQ</a>
      <a href="/contact.html">Connect</a>
    </nav>
    <div class="header-actions">
      <a class="btn primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <button class="menu-toggle" aria-expanded="false" aria-controls="mobile-menu">☰</button>
    </div>
  </header>

  <main>
    <section class="hero" id="hero" aria-labelledby="hero-heading">
      <svg class="pattern" role="img" aria-hidden="true">
        <use href="assets/img/pattern.svg#pattern" />
      </svg>
      <div class="wrap">
        <h1 id="hero-heading">Clearer steps when life asks for a different route.</h1>
        <p class="lead">I offer compassionate, evidence-informed therapy and short, focused pathways so you can begin moving in a direction that feels true for you.</p>
        <div class="hero-actions">
          <a href="{{PRIMARY_CTA_URL}}" class="btn primary-cta-hero">Start a conversation</a>
          <a href="/book.html" class="btn ghost">See availability</a>
        </div>
        <ul class="contact-line">
          <li class="phone">Call: <a href="tel:{{PHONE}}">{{PHONE}}</a></li>
          <li class="email">Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
        </ul>
      </div>
    </section>

    <section class="diagnostic" id="diagnostic" aria-labelledby="diagnostic-heading">
      <div class="wrap-sm">
        <h2 id="diagnostic-heading">Which feeling fits today?</h2>
        <p class="muted">Pick what feels nearest — the recommendation and how we talk about next steps will adapt to what you choose.</p>
        <div class="mood-selector" role="radiogroup" aria-label="Mood to method">
          <button class="mood" data-key="overwhelmed" aria-checked="false">Overwhelmed</button>
          <button class="mood" data-key="stuck" aria-checked="false">Stuck</button>
          <button class="mood" data-key="grieving" aria-checked="false">Grieving</button>
          <button class="mood" data-key="transitioning" aria-checked="false">In transition</button>
          <button class="mood" data-key="anxious" aria-checked="false">Anxious</button>
        </div>

        <div class="method-card" id="methodCard" aria-live="polite">
          <h3 id="methodTitle">Gentle assessment & practical focus</h3>
          <p id="methodDesc">We’ll clarify current priorities, build a short plan tailored to your life, and practice small steps you can use between sessions.</p>
          <div class="method-actions">
            <a id="methodCTA" class="btn primary-cta" href="{{PRIMARY_CTA_URL}}">Book a focused conversation</a>
            <a href="/approach.html" class="btn ghost">How I work</a>
          </div>
        </div>
      </div>
    </section>

    <section class="plan" id="plan" aria-labelledby="plan-heading">
      <div class="wrap">
        <h2 id="plan-heading">Options that respect your time</h2>
        <p class="muted">Short pathways, ongoing support if you want it, and single-session options for targeted moments.</p>

        <div class="plans-grid">
          <article class="plan-card" id="card-1">
            <h4>Short Focus Session</h4>
            <p class="desc">A single 60-minute session to clarify a next step, problem-solve, or get a plan you can try right away.</p>
            <div class="meta">Includes a short follow-up note and two suggested small practices.</div>
            <div class="price">$<span class="price-val">150</span></div>
            <a href="/book.html" class="btn">Book single session</a>
          </article>

          <article class="plan-card" id="card-2">
            <h4>Pathway Package — 6 weeks</h4>
            <p class="desc">A compact, structured series for a tight focus — skill-building, planning, and measurable steps.</p>
            <div class="meta">Six sessions scheduled over 6–8 weeks + short check-ins.</div>
            <div class="price">Package: $<span class="price-val" data-package="840">840</span> <span class="monthly-hide">(~$140/session)</span></div>
            <a href="/fees.html" class="btn">Reserve a pathway</a>
          </article>

          <article class="plan-card" id="card-3">
            <h4>Ongoing Support</h4>
            <p class="desc">Monthly rhythm for steady work on longer patterns and real-life application between sessions.</p>
            <div class="meta">Flexible schedule, priority scheduling, and optional add-ons.</div>
            <div class="price">/month: $<span class="price-val" data-monthly="240">240</span></div>
            <a href="/fees.html" class="btn">Discuss ongoing support</a>
          </article>
        </div>

        <div class="pricing-comparator" aria-hidden="false">
          <label class="switch">
            <input type="checkbox" id="pricingToggle" aria-label="Toggle pricing view">
            <span class="slider"></span>
          </label>
          <div class="toggle-labels">
            <span>Monthly</span>
            <span>Package</span>
          </div>
          <div class="comparator-note">Numbers animate to show equivalent pricing frames.</div>
        </div>
      </div>
    </section>

    <section class="micro-habits" id="micro-habits" aria-labelledby="micro-heading">
      <div class="wrap-sm">
        <h2 id="micro-heading">Small practices you can try this week</h2>
        <div class="habit-grid">
          <div class="habit">Two-minute grounding break — notice breath.</div>
          <div class="habit">List one thing you can change within 24 hours.</div>
          <div class="habit">Set a tiny behavior test and report back next session.</div>
        </div>
        <p class="muted">These are practical experiments, not pressure. We choose what feels doable together.</p>
      </div>
    </section>

    <section class="cta" id="cta" aria-labelledby="cta-heading">
      <div class="wrap-cta">
        <h2 id="cta-heading">Ready to explore what might help next?</h2>
        <p class="muted">I aim for clarity, compassion, and practical next steps. Sessions are confidential; see footer for scope and crisis information.</p>
        <div class="cta-actions">
          <a id="primaryCtaBtn" class="btn primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a href="/contact.html" class="btn ghost">Contact & insurance info</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap-sm footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}}</address>
        <div>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
      <div>
        <h4>Practical notes</h4>
        <p class="muted">Sessions are confidential within legal and ethical limits. I provide psychotherapy within my licensed scope. If you are in crisis or require emergency care, call local emergency services or a crisis line immediately.</p>
      </div>
      <div>
        <h4>Quick links</h4>
        <nav>
          <a href="/about.html">About</a>
          <a href="/fees.html">Fees</a>
          <a href="/book.html">Book</a>
          <a href="/faq.html">FAQ</a>
        </nav>
      </div>
    </div>
    <div class="legal">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
