{"path":"assets/css/styles.css","content":"/* Minimal, self-contained styles — no external fonts */
:root{
  --bg:#fbfdfd;--muted:#6b7171;--accent:#2b5f5f;--accent-2:#7aa6a6;--card:#ffffff;--glass:rgba(255,255,255,0.7);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#123;line-height:1.4;background:var(--bg)}
.wrap{max-width:980px;margin:0 auto;padding:48px 20px}
.wrap-sm{max-width:860px;margin:0 auto;padding:36px 20px}
.wrap-cta{max-width:760px;margin:0 auto;padding:48px 20px;text-align:center}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid rgba(0,0,0,0.04);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.9),rgba(255,255,255,0.6));backdrop-filter:blur(4px);z-index:30}
.brand{display:flex;gap:12px;align-items:center}
.logo{width:52px;height:52px}
.business-name{font-weight:700}
.tagline{font-size:13px;color:var(--muted)}
.main-nav{display:flex;gap:14px}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px 6px}
.header-actions{display:flex;gap:10px;align-items:center}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;text-decoration:none;color:#083; background:transparent;border:1px solid rgba(8,51,51,0.06)}
.btn.ghost{background:transparent;border:1px solid rgba(8,51,51,0.08)}
.btn.primary-cta, .btn.primary-cta-hero{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;border:none}
.menu-toggle{display:none;background:transparent;border:0}

.hero{position:relative;padding:64px 0 80px;background:linear-gradient(180deg,#f7f9f9 0%,#ffffff 100%);overflow:hidden}
.hero .pattern{position:absolute;right:-10%;top:-10%;width:420px;height:420px;opacity:0.12}
.hero .lead{color:var(--muted);max-width:60%}
.hero-actions{display:flex;gap:12px;margin-top:18px}
.contact-line{list-style:none;padding:0;display:flex;gap:12px;margin-top:16px;color:var(--muted)}
.contact-line a{color:inherit}

.diagnostic{background:transparent;padding:40px 0}
.mood-selector{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
.mood{background:var(--card);border-radius:999px;padding:10px 14px;border:1px solid rgba(0,0,0,0.06);cursor:pointer}
.mood[aria-checked="true"]{background:linear-gradient(90deg,var(--accent-2),var(--accent));color:white;border:none;transform:translateY(-3px)}
.method-card{margin-top:18px;padding:20px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));box-shadow:0 6px 18px rgba(17,24,24,0.06)}
.method-actions{display:flex;gap:10px;margin-top:12px}

.plan{padding:36px 0}
.plans-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:18px}
.plan-card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
.plan-card .price{margin-top:12px;font-weight:700}
.price-val{font-feature-settings: "tnum" 1}
.pricing-comparator{display:flex;align-items:center;gap:12px;margin-top:18px}
.switch{position:relative;width:62px;height:32px}
.switch input{display:none}
.slider{position:absolute;inset:0;background:rgba(0,0,0,0.06);border-radius:999px}
.switch input:checked + .slider{background:linear-gradient(90deg,var(--accent-2),var(--accent))}
.switch input + .slider::after{content:"";position:absolute;top:4px;left:4px;width:24px;height:24px;background:white;border-radius:50%;transition:transform 300ms}
.switch input:checked + .slider::after{transform:translateX(30px)}
.toggle-labels{display:flex;gap:8px;color:var(--muted)}
.comparator-note{color:var(--muted);margin-left:8px}

.micro-habits{padding:32px 0;background:#fff}
.habit-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-top:18px}
.habit{background:linear-gradient(180deg,#fff,#fbffff);padding:14px;border-radius:8px;border:1px solid rgba(0,0,0,0.03)}

.cta{padding:48px 0;background:linear-gradient(180deg,#ffffff,#f8fdfd)}
.cta .btn{font-weight:600}

.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:28px 20px;margin-top:40px;background:transparent}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}
.legal{text-align:center;color:var(--muted);padding-top:12px}
.muted{color:var(--muted)}

@media (max-width:900px){
  .lead{max-width:100%}
  .main-nav{display:none}
  .menu-toggle{display:block}
  .wrap{padding:28px 16px}
  .wrap-sm{padding:20px 16px}
  .footer-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Interactive behavior for Pricing Comparator and Mood-to-Method
document.addEventListener('DOMContentLoaded',function(){
  // Set current year
  var yr = document.getElementById('year'); if(yr) yr.textContent = new Date().getFullYear();

  // Pricing comparator
  var toggle = document.getElementById('pricingToggle');
  var monthlyEls = document.querySelectorAll('[data-monthly]');
  var packageEls = document.querySelectorAll('[data-package]');

  // parse numbers
  function parseNum(el){ return Number(el.getAttribute('data-monthly') || el.getAttribute('data-package') || el.textContent.replace(/[^0-9.]/g,'')) }

  function animateValue(el, start, end, duration){
    var startTime = null;
    var step = function(time){
      if(!startTime) startTime = time;
      var progress = Math.min((time - startTime)/duration,1);
      var val = Math.round(start + (end-start)*progress);
      el.textContent = val;
      if(progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  function showMonthly(){
    // show monthly values if data-monthly present; otherwise compute from package
    monthlyEls.forEach(function(el){
      var to = parseNum(el);
      var cur = Number(el.textContent.replace(/[^0-9.]/g,'')) || 0;
      animateValue(el,cur,to,500);
    });
    packageEls.forEach(function(el){
      // convert package to monthly estimate if data-package exists
      var pkg = Number(el.getAttribute('data-package')) || parseNum(el);
      var to = Math.round(pkg / 6); // assume 6-week pathway conversion
      var cur = Number(el.textContent.replace(/[^0-9.]/g,'')) || 0;
      animateValue(el,cur,to,500);
    });
  }
  function showPackage(){
    packageEls.forEach(function(el){
      var to = Number(el.getAttribute('data-package')) || parseNum(el);
      var cur = Number(el.textContent.replace(/[^0-9.]/g,'')) || 0;
      animateValue(el,cur,to,500);
    });
    monthlyEls.forEach(function(el){
      var monthly = Number(el.getAttribute('data-monthly')) || parseNum(el);
      var to = Math.round(monthly * 6); // convert to package estimate
      var cur = Number(el.textContent.replace(/[^0-9.]/g,'')) || 0;
      animateValue(el,cur,to,500);
    });
  }

  if(toggle){
    toggle.addEventListener('change',function(){
      if(toggle.checked){
        document.querySelectorAll('.monthly-hide').forEach(function(n){n.style.display='inline'});
        showPackage();
      } else {
        document.querySelectorAll('.monthly-hide').forEach(function(n){n.style.display='none'});
        showMonthly();
      }
    });
    // initialize to monthly
    toggle.checked = false; document.querySelectorAll('.monthly-hide').forEach(function(n){n.style.display='none'}); showMonthly();
  }

  // Mood-to-Method selector
  var moods = document.querySelectorAll('.mood');
  var methodTitle = document.getElementById('methodTitle');
  var methodDesc = document.getElementById('methodDesc');
  var methodCTA = document.getElementById('methodCTA');
  var primaryCtaBtn = document.getElementById('primaryCtaBtn');

  var map = {
    'overwhelmed':{
      title: 'Short anchors and immediate choices',
      desc: 'We prioritize calming practices, a brief safety plan if needed, and a tiny set of doable tasks to ease everyday pressure.',
      cta: 'Schedule a short support session',
      url: '{{PRIMARY_CTA_URL}}?focus=calm'
    },
    'stuck':{
      title: 'Break the loop — clarify a next step',
      desc: 'We map what keeps you stuck, try a small behavioral experiment, and make a plan designed to test change with low risk.',
      cta: 'Book a focused planning session',
      url: '{{PRIMARY_CTA_URL}}?focus=plan'
    },
    'grieving':{
      title: 'Gentle space for loss',
      desc: 'Support that honors time and feeling, with attention to routines and tasks that help maintain functioning while you grieve.',
      cta: 'Find a session for grief support',
      url: '{{PRIMARY_CTA_URL}}?focus=grief'
    },
    'transitioning':{
      title: 'A map for the new chapter',
      desc: 'We look at values and goals, planning steps that match your priorities and the practical realities of change.',
      cta: 'Explore a pathway package',
      url: '{{PRIMARY_CTA_URL}}?focus=transition'
    },
    'anxious':{
      title: 'Skills, structure, and small exposure',
      desc: 'We develop coping tools, practice them in small doses, and shape a plan to reduce avoidance while staying compassionate with yourself.',
      cta: 'Start with an anxiety-focused session',
      url: '{{PRIMARY_CTA_URL}}?focus=anxiety'
    }
  };

  moods.forEach(function(btn){
    btn.addEventListener('click',function(){
      moods.forEach(function(b){b.setAttribute('aria-checked','false')});
      btn.setAttribute('aria-checked','true');
      var key = btn.getAttribute('data-key');
      var data = map[key];
      if(data){
        // animate text crossfade
        methodTitle.style.opacity=0; methodDesc.style.opacity=0; methodCTA.style.opacity=0;
        setTimeout(function(){
          methodTitle.textContent = data.title;
          methodDesc.textContent = data.desc;
          methodCTA.textContent = data.cta;
          methodCTA.setAttribute('href', data.url);
          if(primaryCtaBtn){ primaryCtaBtn.textContent = data.cta; primaryCtaBtn.setAttribute('href', data.url); }
          methodTitle.style.opacity=1; methodDesc.style.opacity=1; methodCTA.style.opacity=1;
        },260);
      }
    });
  });

  // Mobile menu toggle
  var menuToggle = document.querySelector('.menu-toggle');
  var mainNav = document.querySelector('.main-nav');
  menuToggle && menuToggle.addEventListener('click',function(){
    var open = this.getAttribute('aria-expanded') === 'true';
    this.setAttribute('aria-expanded', String(!open));
    if(mainNav) mainNav.style.display = open ? 'none' : 'flex';
  });
});"} 
